// The in-memory keyword index behind the typeahead, and the merge of its
// matches with the server's suggestions.
import MiniSearch from "minisearch";

export function toSearchItem(result) {
  return { id: result.id, kind: result.kind, text: result.text, subtext: result.subtext ?? null, url: result.url ?? null, uri: result.image?.uri ?? null, isRecent: result.is_recent === true };
}

export function buildSearchIndex(keywords) {
  const index = new MiniSearch({ fields: ["text"], storeFields: ["kind", "text", "subtext", "url", "uri"] });
  index.addAll(keywords.map(toSearchItem));
  return index;
}

// Server suggestions first, then local matches by score, without duplicates.
export function mergeSearchResults(query, serverResults, index, limit = 10) {
  const seen = new Set();
  const merged = [];
  const add = (item) => {
    if (!seen.has(item.id) && merged.length < limit) {
      seen.add(item.id);
      merged.push(item);
    }
  };
  for (const result of serverResults) {
    add(toSearchItem(result));
  }
  for (const match of index.search(query, { prefix: true })) {
    add({ id: match.id, kind: match.kind, text: match.text, subtext: match.subtext, url: match.url, uri: match.uri, isRecent: false });
  }
  return merged;
}
