// A recent search, with a button that removes it from the list.
import * as stylex from "@stylexjs/stylex";
import { typeaheadItemTokens } from "ComponentTokens.stylex";
import UIPressable from "UIPressable.react";
import UIIconButton from "UIIconButton.react";
import UIText from "UIText.react";
import { UIRow, UIColumn } from "UIStack.react";
import SearchResultIcon from "SearchResultIcon.react";

const styles = stylex.create({
  wrapper: { gap: 4 },
  row: { gap: typeaheadItemTokens.gap, paddingInline: 8, minHeight: 52, borderRadius: typeaheadItemTokens.radius, flexGrow: 1, minWidth: 0 },
  active: { backgroundColor: typeaheadItemTokens.backgroundSelected },
});

export default function SearchRecentRow({ id, item, active, onSelect, onRemove }) {
  return (
    <UIRow role="presentation" xstyle={styles.wrapper}>
      <UIPressable id={id} role="option" aria-selected={active} label={item.text} testid="search-recent" onPress={() => onSelect(item)} xstyle={[styles.row, active && styles.active]}>
        <SearchResultIcon item={item} />
        <UIColumn grow>
          <UIText weight="medium" numberOfLines={1}>
            {item.text}
          </UIText>
          {item.subtext ? (
            <UIText type="meta" color="secondary" numberOfLines={1}>
              {item.subtext}
            </UIText>
          ) : null}
        </UIColumn>
      </UIPressable>
      <UIIconButton icon="close" label={`Remove ${item.text} from recent searches`} size={32} iconSize={16} filled={false} onPress={() => onRemove(item.id)} />
    </UIRow>
  );
}
