// One suggestion in the typeahead's listbox.
import * as stylex from "@stylexjs/stylex";
import { typeaheadItemTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIPressable from "UIPressable.react";
import UIText from "UIText.react";
import { UIColumn } from "UIStack.react";
import SearchResultIcon from "SearchResultIcon.react";
import SearchHighlightedText from "SearchHighlightedText.react";

const styles = stylex.create({
  row: { gap: typeaheadItemTokens.gap, paddingInline: 8, minHeight: 52, borderRadius: typeaheadItemTokens.radius },
  active: { backgroundColor: typeaheadItemTokens.backgroundSelected },
});

export default function SearchTypeaheadRow({ id, item, query, active, onSelect }) {
  const isSearch = item.kind === "SEARCH";
  return (
    <UIPressable id={id} role="option" aria-selected={active} label={item.text} block testid="search-result" onPress={() => onSelect(item)} xstyle={[styles.row, active && styles.active]}>
      <SearchResultIcon item={item} />
      <UIColumn grow>
        {isSearch ? (
          <UIText weight="medium" numberOfLines={1}>
            {fbt("Search for " + fbt.param("query", item.text), "typeahead row that searches for the typed text")}
          </UIText>
        ) : (
          <SearchHighlightedText text={item.text} query={query} />
        )}
        {item.subtext ? (
          <UIText type="meta" color="secondary" numberOfLines={1}>
            {item.subtext}
          </UIText>
        ) : null}
      </UIColumn>
    </UIPressable>
  );
}
