// A suggestion's text with the part that matches the query, at the start of
// the text or of one of its words, in bold.
import UIText from "UIText.react";

function matchStart(text, query) {
  const lower = text.toLowerCase();
  const needle = query.toLowerCase();
  if (lower.startsWith(needle)) {
    return 0;
  }
  const wordStart = lower.indexOf(` ${needle}`);
  return wordStart < 0 ? -1 : wordStart + 1;
}

export default function SearchHighlightedText({ text, query }) {
  const start = query ? matchStart(text, query) : -1;
  if (start < 0) {
    return (
      <UIText weight="medium" numberOfLines={1}>
        {text}
      </UIText>
    );
  }
  const end = start + query.length;
  return (
    <UIText weight="medium" numberOfLines={1}>
      {text.slice(0, start)}
      <UIText weight="bold">{text.slice(start, end)}</UIText>
      {text.slice(end)}
    </UIText>
  );
}
