// The picture of a suggestion: the profile picture of a person, page or
// group, or a glyph in a circle for keywords and recent searches.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIAvatar from "UIAvatar.react";
import UIIcon from "UIIcon.react";

const styles = stylex.create({
  well: { display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: "50%", backgroundColor: colors.secondaryButtonBackground, flexShrink: 0 },
  accent: { backgroundColor: colors.accent },
});

export default function SearchResultIcon({ item }) {
  if (item.uri) {
    return <UIAvatar src={item.uri} size={36} />;
  }
  const icon = item.kind === "SEARCH" ? "search" : item.isRecent ? "clock" : "search";
  return (
    <span {...stylex.props(styles.well, item.kind === "SEARCH" && styles.accent)}>
      <UIIcon name={icon} size={18} color={item.kind === "SEARCH" ? "onAccent" : "primary"} />
    </span>
  );
}
