// The heading above a group of suggestions, with an optional action.
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import UIButton from "UIButton.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  header: { paddingInline: 8, paddingBlock: 4, minHeight: 36 },
});

export default function SearchTypeaheadSectionHeader({ title, actionLabel = null, onAction }) {
  return (
    <UIRow role="presentation" justify="between" xstyle={styles.header}>
      <UIText type="headline4">{title}</UIText>
      {actionLabel ? <UIButton use="tertiary" size="small" label={actionLabel} onPress={onAction} /> : null}
    </UIRow>
  );
}
