// The search typeahead. When the field is focused it shows the recent
// searches and indexes the bootstrap keywords in memory; for each query it
// requests the server's suggestions (debounced, flushed explicitly in the
// benchmark) and merges them with the local matches.
import { useEffect, useId, useMemo, useRef, useState } from "react";
import { fetchQuery, graphql, useLazyLoadQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { typeaheadTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import RelayEnvironment from "RelayEnvironment";
import { deferUntilFlush, cancelDeferred } from "TimerGuard";
import { emitStepEvent } from "Workload";
import LoggingSurface from "LoggingSurface.react";
import { UIColumn } from "UIStack.react";
import SearchTypeaheadSectionHeader from "SearchTypeaheadSectionHeader.react";
import SearchTypeaheadRow from "SearchTypeaheadRow.react";
import SearchRecentRow from "SearchRecentRow.react";
import { buildSearchIndex, mergeSearchResults, toSearchItem } from "SearchIndex";

const styles = stylex.create({
  panel: { position: "absolute", top: 46, left: -8, zIndex: 30, width: 328, maxHeight: "calc(100vh - 72px)", overflowY: "auto", boxSizing: "border-box", padding: typeaheadTokens.paddingX, borderRadius: typeaheadTokens.radius, backgroundColor: colors.popoverBackground, boxShadow: elevation.e4 },
});

const DEFER_KEY = "search-typeahead";

const ResultsQuery = graphql`
  query SearchTypeaheadPanelResultsQuery($query: String!) {
    search_typeahead(query: $query, first: 8) {
      query
      results {
        id
        kind
        text
        subtext
        url
        is_recent
        image {
          uri
        }
      }
    }
  }
`;

export default function SearchTypeaheadPanel({ query, onClose, inputRef }) {
  const bootstrap = useLazyLoadQuery(
    graphql`
      query SearchTypeaheadPanelBootstrapQuery {
        search_typeahead(query: "") {
          results {
            id
            kind
            text
            subtext
            url
            is_recent
            image {
              uri
            }
          }
          bootstrap_keywords {
            id
            kind
            text
            subtext
            url
            is_recent
            image {
              uri
            }
          }
        }
      }
    `,
    {},
    { fetchPolicy: "store-or-network" },
  );
  const listId = useId();
  const panelRef = useRef(null);
  const trimmed = query.trim();
  const index = useMemo(() => buildSearchIndex(bootstrap.search_typeahead?.bootstrap_keywords ?? []), [bootstrap]);
  const [removedIds, setRemovedIds] = useState([]);
  const [server, setServer] = useState(null);
  const [activeIndex, setActiveIndex] = useState(-1);

  const items = useMemo(() => {
    if (trimmed === "") {
      return (bootstrap.search_typeahead?.results ?? []).filter((result) => !removedIds.includes(result.id)).map(toSearchItem);
    }
    const serverResults = server?.query === trimmed ? server.results : [];
    return [{ id: "search:all", kind: "SEARCH", text: trimmed, subtext: null, url: null, uri: null, isRecent: false }, ...mergeSearchResults(trimmed, serverResults, index)];
  }, [bootstrap, trimmed, server, index, removedIds]);

  useEffect(() => {
    setActiveIndex(-1);
  }, [trimmed]);

  useEffect(() => {
    if (trimmed === "") {
      return undefined;
    }
    let cancelled = false;
    deferUntilFlush(DEFER_KEY, () => {
      fetchQuery(RelayEnvironment, ResultsQuery, { query: trimmed })
        .toPromise()
        .then((data) => {
          if (!cancelled) {
            setServer({ query: trimmed, results: data?.search_typeahead?.results ?? [] });
          }
        });
    });
    return () => {
      cancelled = true;
      cancelDeferred(DEFER_KEY);
    };
  }, [trimmed]);

  useEffect(() => {
    if (trimmed !== "" && server?.query === trimmed) {
      emitStepEvent("search-results", { query: trimmed });
    }
  }, [trimmed, server]);

  useEffect(() => {
    const input = inputRef.current;
    if (!input) {
      return undefined;
    }
    input.setAttribute("aria-controls", listId);
    const onKeyDown = (event) => {
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        const down = event.key === "ArrowDown";
        setActiveIndex((current) => {
          if (items.length === 0) {
            return -1;
          }
          return down ? (current + 1) % items.length : current <= 0 ? items.length - 1 : current - 1;
        });
      } else if (event.key === "Enter" && activeIndex >= 0 && items[activeIndex]) {
        event.preventDefault();
        onClose();
      }
    };
    input.addEventListener("keydown", onKeyDown);
    return () => {
      input.removeEventListener("keydown", onKeyDown);
      input.removeAttribute("aria-controls");
      input.removeAttribute("aria-activedescendant");
    };
  }, [inputRef, listId, items, activeIndex, onClose]);

  useEffect(() => {
    const input = inputRef.current;
    if (activeIndex >= 0) {
      input?.setAttribute("aria-activedescendant", `${listId}-${activeIndex}`);
    } else {
      input?.removeAttribute("aria-activedescendant");
    }
  }, [inputRef, listId, activeIndex]);

  useEffect(() => {
    const onPointerDown = (event) => {
      if (!panelRef.current?.contains(event.target) && !inputRef.current?.contains(event.target)) {
        onClose();
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [inputRef, onClose]);

  const removeRecent = (id) => setRemovedIds((current) => [...current, id]);

  return (
    <LoggingSurface name="search_typeahead">
      <div ref={panelRef} id={listId} role="listbox" aria-label="Search suggestions" data-testid="search-typeahead" {...stylex.props(styles.panel)}>
        <UIColumn gap={2}>
          {trimmed === "" ? (
            <>
              <SearchTypeaheadSectionHeader title={fbt("Recent searches", "heading of the recent searches in the search typeahead")} actionLabel="Edit" />
              {items.map((item, i) => (
                <SearchRecentRow key={item.id} id={`${listId}-${i}`} item={item} active={i === activeIndex} onSelect={onClose} onRemove={removeRecent} />
              ))}
            </>
          ) : (
            items.map((item, i) => <SearchTypeaheadRow key={item.id} id={`${listId}-${i}`} item={item} query={trimmed} active={i === activeIndex} onSelect={onClose} />)
          )}
        </UIColumn>
      </div>
    </LoggingSurface>
  );
}
